'use strict';
function createRouter() {
  function router(req, res, next) { if (typeof next === 'function') next(); }
  router.stack = [];
  router.use = function () { router.stack.push({ method: 'use', args: Array.from(arguments) }); return router; };
  ['get','post','options','put','patch','delete'].forEach(function (method) {
    router[method] = function () { router.stack.push({ method, args: Array.from(arguments) }); return router; };
  });
  return router;
}
function express() { return createRouter(); }
express.Router = createRouter;
express.json = function () { return function (_req,_res,next) { if (next) next(); }; };
express.urlencoded = express.json;
express.static = function () { return function (_req,_res,next) { if (next) next(); }; };
module.exports = express;
